istant has read'=>'Көмекшінің не оқығаны','%1$d pages read · %2$d waiting · %3$d with errors · %4$d passages · %5$d understood by meaning'=>'%1$d бет оқылды · %2$d күтуде · %3$d қателері бар · %4$d үзінді · %5$d мағынасы бойынша түсінікті','Embedding model: %s'=>'Енгізу моделі: %s','No embedding model: search is by words only. Connect Google Gemini, OpenAI, Mistral or OpenRouter to search by meaning.'=>'Енгizу моделi жоқ: іздеу тек сөздер арқылы орындалады. Мән бойынша іздеу үшін Google Gemini, OpenAI, Mistral немесе OpenRouter қызметін қосыңыз.','Building meanings is paused:'=>'Мағыналарды құрастыру тоқтатылды:','Re-read the whole site'=>'Бүкіл сайтты қайта оқу','Rebuild all meanings'=>'Барлық мағыналарды қайта құру','Filter by title or address'=>'Ataky немесе мекенжай бойынша сүзу','Read'=>'Оқу','Waiting'=>'Күтуде','Errors'=>'Қателер','Passages'=>'Үзінділер','by meaning'=>'мәні бойынша','Rebuild meaning'=>'Мағынаны қайта құру','Done ✓'=>'Орындалды ✓','Failed'=>'Сәтсіз аяқталды']];